/* Special: for page sections and cards (backdrop, center, spacing) */
.section-center {
  width: 100vw;
  min-height: 72vh;
  align-items: center;
  display: flex;
  justify-content: center;
  flex-direction: column;
  padding: 44px 0 23px 0;
  background: transparent;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius-l);
  border: 1.5px solid var(--card-outline);
  box-shadow: var(--shadow-s);
  padding: 26px 32px;
  margin-bottom: 23px;
  max-width: 470px;
  width: 100%;
}

@media (max-width: 480px) {
  .card {
    padding: 17px 8px;
    margin-bottom: 15px;
    max-width: 100vw;
  }
  .section-center {
    padding: 22px 0 9px 0;
  }
}

