  width: 100vw;
  min-height: 72vh;
  align-items: center;
  display: flex;
  justify-content: center;
  flex-direction: column;
  padding: 44px 0 23px 0;
  background: transparent;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius-l);
  border: 1.5px solid var(--card-outline);
  box-shadow: var(--shadow-s);
  padding: 26px 32px;
  margin-bottom: 23px;
  max-width: 470px;
  width: 100%;
}

@media (max-width: 480px) {
  .card {
    padding: 17px 8px;
    margin-bottom: 15px;
    max-width: 100vw;
  }
  .section-center {
    padding: 22px 0 9px 0;
  }
}

/* Utility & helper classes for centering, separating, and visually calming layouts */
.flex-center {
  display: flex;
  justify-content: center;
  align-items: center;
}

.input, .input-text, .input-area {
  border: 1.5px solid var(--card-outline);
  border-radius: var(--radius-s);
  background: #fff;
  font-size: 1rem;
  padding: 10px 13px;
  color: var(--text-dark);
  margin-bottom: 4px;
  width: 100%;
  transition: border-color 0.19s cubic-bezier(.68,0,.29,1.17);
}

.input:focus, .input-text:focus, .input-area:focus {
  border-color: var(--primary);
  outline: none;
}

input[disabled], .btn[disabled], button[disabled] {
  opacity: 0.62 !important;
  cursor: not-allowed !important;
}

::-webkit-input-placeholder { color: #b2bdd6; }
::-moz-placeholder { color: #b2bdd6; }
:-ms-input-placeholder { color: #b2bdd6; }
::placeholder { color: #b2bdd6; }

hr {
  background: var(--card-outline);
  opacity: 0.54;
  border: none;
  height: 1px;
  margin: 24px 0;
} 
/* Universal responsive utilities */
@media (max-width: 700px) {
  .navbar { padding: 11px 0; font-size: 1.03rem; }
  .navbar .container { padding: 0 13px !important; }
}

@media (max-width: 450px) {
  .navbar { font-size: 0.94rem; }
  .logo { font-size: 1.03rem; }
}

